(-.55,.45,.5),([-.99,.95],[-.9,1],[0,.99]),('Late technical intervention permits strong support with ordinary rights uncertain.','Human-derived agency is central with machine/technical concentration possible.','Useful active roles and Merlin’s help count; sleep and elapsed eras are excluded.'),
